INSERT INTO `quest_greeting_locale` (`ID`, `type`, `locale`, `Greeting`, `VerifiedBuild`) VALUES (1344,0,'zhTW','雖然我們在這片廢墟這裡正經歷一段清閒的時期，但我相信這不會持續太久。不過在此期間，我可以用得上像你這樣的人。你願意幫助矮人探險者協會嗎？',0);
