INSERT INTO `quest_greeting_locale` (`ID`, `type`, `locale`, `Greeting`, `VerifiedBuild`) VALUES (2700,0,'zhTW','我們在庇護點守著阿拉希高地僅存的少數斯特隆加德領土。而我們正在節節敗退……$B$B如果你有話要對我說，希望是好消息。',0);
