INSERT INTO `quest_greeting_locale` (`ID`, `type`, `locale`, `Greeting`, `VerifiedBuild`) VALUES (2786,0,'zhTW','歡迎來到骨握的符文與末日之店，$c。你可以看，但不可以摸。$B$B這裡有些知識並不是給……未經啟蒙者準備的。',0);
