INSERT INTO `quest_greeting_locale` (`ID`, `type`, `locale`, `Greeting`, `VerifiedBuild`) VALUES (2860,0,'zhTW','那可真是一場倉促的撤離，我跟你說，$c。我們把所有能拿走、能快速搬走的東西都抓了就跑。所以我們現在的補給有點吃緊。',0);
