INSERT INTO `quest_greeting_locale` (`ID`, `type`, `locale`, `Greeting`, `VerifiedBuild`) VALUES (2910,0,'zhTW','那些渾蛋趁夜襲擊我們，那時我們才剛喝了幾杯酒。不然的話，我們絕對能打贏他們，這點你可以放心。$B$B現在大家都死了……只剩下我們幾個。',0);
DELETE FROM `quest_greeting_locale` WHERE `ID` = 2920 AND `type` = 0 AND `locale` = 'zhTW';
INSERT INTO `quest_greeting_locale` (`ID`, `type`, `locale`, `Greeting`, `VerifiedBuild`) VALUES (2920,0,'zhTW','嘿，你好啊，$N。$B$B洛特威爾不是我遇過最敏銳的老闆。他其實對自己的工作太過投入了。投入到有時候他的僕人們甚至沒飯吃，也沒薪水拿。$B$B<盧西安對著洛特威爾皺起了眉頭。>$B$B但這不代表你就該跟著受苦。',0);
DELETE FROM `quest_greeting_locale` WHERE `ID` = 2921 AND `type` = 0 AND `locale` = 'zhTW';
INSERT INTO `quest_greeting_locale` (`ID`, `type`, `locale`, `Greeting`, `VerifiedBuild`) VALUES (2921,0,'zhTW','你能來真是太好了，$c。$B$B我叫魯特維爾·沃拉圖斯，是啟蒙祕法學、煉金術與工程科學協會的創始成員之一：我們致力於將艾澤拉斯的各項智慧科學融合成一套完整的學問體系。',0);
