INSERT INTO `quest_greeting_locale` (`ID`, `type`, `locale`, `Greeting`, `VerifiedBuild`) VALUES (3188,0,'zhTW','你似乎有什麼想跟我討論的事，$c……來，坐到我這裡來。',0);
