INSERT INTO `quest_greeting_locale` (`ID`, `type`, `locale`, `Greeting`, `VerifiedBuild`) VALUES (5638,0,'zhTW','我在淒涼之地這裡有很多事要忙，$N。羅田要我們幫其中一位客戶收集一些材料，還要找回一些遺失的物品。$B$B既然你來了要幫忙，那我們何不現在就開始？',0);
